// Package pool provides a typed pool of reusable objects that reset their
// state.
//
// [Pool] wraps a [sync.Pool] holding objects of a single type and calls their
// Reset method before an object goes back into the pool. An object obtained
// from [Pool.Get] therefore never carries data from its previous use, and the
// caller needs no type assertions.
//
// The Reset method of a struct can be generated by cmd/reset: mark the struct
// with the comment
//
//	// generate:reset
//
// and run go generate ./...
//
// # Usage
//
//	var bufPool = pool.New(func() *Buffer { return &Buffer{} })
//
//	func handle() {
//		buf := bufPool.Get()
//		defer bufPool.Put(buf)
//		// use buf
//	}
package pool

import "sync"

// Resetter is implemented by objects that can reset their state to the
// initial one.
//
// Reset must leave the object ready to be used again and drop references to
// external data, so that a pooled object does not keep that data from being
// garbage collected. Keeping memory already allocated, such as the capacity of
// slices and buffers, is allowed and desirable.
type Resetter interface {
	Reset()
}

// Pool is a typed pool of objects of type T.
//
// Like [sync.Pool], a Pool may release the objects it holds at any time, so it
// is suited only for reusing temporary objects, not for keeping state.
//
// T is usually a pointer to a struct: Reset then modifies the object itself,
// and Put does not allocate to box the value into an interface.
//
// A Pool is safe for concurrent use by multiple goroutines. A Pool must not be
// copied after first use; create one with [New].
type Pool[T Resetter] struct {
	p sync.Pool
}

// New returns a pool that calls newFn when it has no free objects.
//
// newFn must return an object ready for use. It is required because the zero
// value of a pointer type T is nil.
func New[T Resetter](newFn func() T) *Pool[T] {
	return &Pool[T]{
		p: sync.Pool{New: func() any { return newFn() }},
	}
}

// Get returns an object from the pool or, if the pool is empty, a new object
// created by the function passed to [New].
//
// The returned object is in its initial state: pooled objects have been reset
// by [Pool.Put], new ones come straight from the constructor.
func (p *Pool[T]) Get() T {
	return p.p.Get().(T)
}

// Put resets x by calling x.Reset and returns x to the pool.
//
// x must not be used after Put: it may be handed out by another call to
// [Pool.Get].
func (p *Pool[T]) Put(x T) {
	x.Reset()
	p.p.Put(x)
}
